    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  }).value;

  const r = addLine(invoice, { sku: 'COPY-HOUR', qty: 3 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 2);
  assert.equal(r.value.lines[1].sku, 'COPY-HOUR');
  assert.equal(r.value.lines[1].qty, 3);
  assert.equal(r.value.lines[1].name, 'Copywriting (hour)');
});

test('addLine increments qty if SKU already exists', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 2 }],
  }).value;

  const r = addLine(invoice, { sku: 'DEV-HOUR', qty: 5 });
  assert.equal(r.ok, true);
  assert.equal(r.value.lines.length, 1);
  assert.equal(r.value.lines[0].qty, 7);
});

test('addLine reports QTY_INVALID for non-positive quantities', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'COPY-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'COPY-HOUR', qty: -5 }), { ok: false, error: 'QTY_INVALID' });
  assert.deepEqual(addLine(invoice, { sku: 'COPY-HOUR', qty: 1.5 }), { ok: false, error: 'QTY_INVALID' });
